// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 hash) public {
        vm.assume(actor != address(0) && actor != address(c));

        // lock in a guess
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // move past the target block
        uint256 target = block.number + 1;
        vm.roll(target + 1);

        bytes32 answer = keccak256(abi.encodePacked(blockhash(target)));
        // restrict to losing guesses (correct guesses make settle revert in BOTH versions)
        vm.assume(hash != answer);

        // first settle succeeds in both P and M
        vm.prank(actor);
        bool firstOk;
        try c.settle() { firstOk = true; } catch { firstOk = false; }
        assertTrue(firstOk, "first settle should succeed on a losing guess");

        // general rule: once settled, the guess is cleared and a second settle MUST revert
        vm.prank(actor);
        bool secondOk;
        try c.settle() { secondOk = true; } catch { secondOk = false; }
        assertTrue(!secondOk, "second settle must revert after the guess block was reset");
    }
}
